// Deterministic byte-budget packer for factory context sections.
// Node.js builtins only. See the work order for the exact contract.
import {readFileSync, realpathSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';

function fail(message){
  throw new Error(message);
}

function isPlainObjectLike(value){
  return typeof value==='object'&&value!==null&&!Array.isArray(value);
}

function validate(sections,maxBytes){
  if(!Number.isSafeInteger(maxBytes)||maxBytes<0){
    fail('maxBytes must be a nonnegative safe integer');
  }
  if(!Array.isArray(sections)){
    fail('sections must be an array');
  }
  const seen=new Set();
  for(let i=0;i<sections.length;i++){
    if(!Object.prototype.hasOwnProperty.call(sections,i)){
      fail(`sections[${i}] is a missing array slot`);
    }
    const section=sections[i];
    if(!isPlainObjectLike(section)){
      fail(`sections[${i}] must be a non-null, non-array object`);
    }
    const {id,text,priority,required}=section;
    if(typeof id!=='string'||id.length===0){
      fail(`sections[${i}].id must be a nonempty string`);
    }
    if(typeof text!=='string'){
      fail(`sections[${i}].text must be a string`);
    }
    if(!Number.isSafeInteger(priority)||priority<0){
      fail(`sections[${i}].priority must be a nonnegative safe integer`);
    }
    if(typeof required!=='boolean'){
      fail(`sections[${i}].required must be a boolean`);
    }
    if(seen.has(id)){
      fail(`sections[${i}].id ${JSON.stringify(id)} is not unique`);
    }
    seen.add(id);
  }
}

function frameOf(section){
  return '### '+JSON.stringify(section.id)+'\n'+section.text+'\n';
}

export function packContext(sections,maxBytes){
  validate(sections,maxBytes);
  const entries=sections.map((section,index)=>{
    const frame=frameOf(section);
    return {index,id:section.id,required:section.required,priority:section.priority,
      frame,cost:Buffer.byteLength(frame,'utf8')};
  });
  const chosen=[];
  let used=0;
  for(const entry of entries){
    if(!entry.required) continue;
    used+=entry.cost;
    chosen.push(entry);
  }
  if(used>maxBytes){
    fail(`required sections need ${used} bytes but maxBytes is ${maxBytes}`);
  }
  const optional=entries.filter(entry=>!entry.required)
    .sort((a,b)=>(b.priority-a.priority)||(a.index-b.index));
  const omitted=[];
  for(const entry of optional){
    if(entry.cost<=maxBytes-used){
      used+=entry.cost;
      chosen.push(entry);
    }else{
      omitted.push(entry);
    }
  }
  omitted.sort((a,b)=>a.index-b.index);
  let text='';
  for(const entry of chosen) text+=entry.frame;
  return {text,bytes:used,included:chosen.map(entry=>entry.id),
    omitted:omitted.map(entry=>entry.id)};
}

function runCli(argv){
  try{
    if(argv.length!==1){
      fail('usage: node context-packet.js INPUT_JSON_FILE');
    }
    const raw=readFileSync(argv[0],'utf8');
    const parsed=JSON.parse(raw);
    if(!isPlainObjectLike(parsed)){
      fail('input JSON must be an object with sections and maxBytes');
    }
    const result=packContext(parsed.sections,parsed.maxBytes);
    process.stdout.write(JSON.stringify(result)+'\n');
    process.exitCode=0;
  }catch(error){
    const message=error&&error.message?error.message:String(error);
    process.stderr.write('context-packet: '+message+'\n');
    process.exitCode=2;
  }
}

function isMainModule(){
  const entry=process.argv[1];
  if(typeof entry!=='string'||entry.length===0) return false;
  const candidates=[resolve(entry)];
  try{ candidates.push(realpathSync(entry)); }catch{ /* keep resolved path */ }
  return candidates.some(path=>pathToFileURL(path).href===import.meta.url);
}

if(isMainModule()){
  runCli(process.argv.slice(2));
}
