import test from 'node:test';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {packContext} from '../context-packet.js';

const here=dirname(fileURLToPath(import.meta.url));
const script=join(here,'..','context-packet.js');
const section=(id,text,priority=0,required=false)=>({id,text,priority,required});
const cost=(id,text)=>Buffer.byteLength('### '+JSON.stringify(id)+'\n'+text+'\n','utf8');

function withFixture(contents,run){
  const dir=mkdtempSync(join(tmpdir(),'context-packet-'));
  try{
    const file=join(dir,'input.json');
    if(contents!==null) writeFileSync(file,contents,'utf8');
    return run(file);
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
}

const cli=(...args)=>spawnSync(process.execPath,[script,...args],{encoding:'utf8'});

test('input validation rejects bad shapes without coercion',()=>{
  const bad=[
    [null,0],[{},0],['x',0],
    [[],-1],[[],1.5],[[],'1'],[[],Number.MAX_SAFE_INTEGER+1],[[],NaN],
    [[null],0],[[[]],0],[['s'],0],
    [[section('','x')],0],[[section(1,'x')],0],
    [[section('a',1)],0],[[section('a',null)],0],
    [[section('a','x',-1)],0],[[section('a','x',1.5)],0],[[section('a','x','1')],0],
    [[section('a','x',0,'true')],0],[[section('a','x',0,1)],0],
    [[{id:'a',text:'x',priority:0}],0],
    [[section('a','x'),section('a','y')],1000],
  ];
  for(const [sections,maxBytes] of bad){
    assert.throws(()=>packContext(sections,maxBytes),Error,JSON.stringify([sections,maxBytes]));
  }
  assert.throws(()=>packContext([section('ok','x'),section('','')],0),Error);
});

test('ids are case sensitive and exotic ids are accepted',()=>{
  const ids=['a','A','__proto__','with space','\n','\0','雪 ❄'];
  const result=packContext(ids.map(id=>section(id,'t')),10000);
  assert.deepEqual(result.included,ids);
  assert.equal(result.text,ids.map(id=>'### '+JSON.stringify(id)+'\nt\n').join(''));
});

test('required kept in input order, optional by priority then input order',()=>{
  const input=[section('o1','a',5),section('r1','b',0,true),section('o2','c',9),
    section('r2','d',100,true),section('o3','e',5)];
  const result=packContext(input,10000);
  assert.deepEqual(result.included,['r1','r2','o2','o1','o3']);
  assert.deepEqual(result.omitted,[]);
  assert.equal(result.bytes,Buffer.byteLength(result.text,'utf8'));
});

test('skip continues to later smaller sections and omitted is in input order',()=>{
  const input=[section('small1','1',1),section('huge','x'.repeat(50),9),
    section('mid','yy',5),section('small2','2',1)];
  const budget=cost('mid','yy')+cost('small1','1')+cost('small2','2');
  const result=packContext(input,budget);
  assert.deepEqual(result.included,['mid','small1','small2']);
  assert.deepEqual(result.omitted,['huge']);
  assert.equal(result.bytes,budget);
});

test('required exact fit succeeds and one byte less throws',()=>{
  const input=[section('r','é',0,true),section('o','z',1)];
  const need=cost('r','é');
  assert.deepEqual(packContext(input,need),{text:'### "r"\né\n',bytes:need,included:['r'],omitted:['o']});
  assert.throws(()=>packContext(input,need-1),Error);
});

test('zero budget with only optional sections omits everything',()=>{
  assert.deepEqual(packContext([section('a','x',3),section('b','y',7)],0),
    {text:'',bytes:0,included:[],omitted:['a','b']});
});

test('text is not trimmed or normalized',()=>{
  const text='  \r\n\ttrailing \n\n';
  const result=packContext([section('t',text)],1000);
  assert.equal(result.text,'### "t"\n'+text+'\n');
});

test('CLI success prints one JSON line and nothing on stderr',()=>{
  const input={sections:[section('a','x',1),section('b','é',0,true)],maxBytes:100,extra:true};
  withFixture(JSON.stringify(input),file=>{
    const run=cli(file);
    assert.equal(run.status,0);
    assert.equal(run.stderr,'');
    assert.equal(run.stdout,JSON.stringify(packContext(input.sections,input.maxBytes))+'\n');
  });
});

test('CLI failures exit 2 with stderr and no stdout',()=>{
  const cases=[
    ()=>cli(),
    ()=>withFixture('{}',file=>cli(file,file)),
    ()=>withFixture(null,file=>cli(file)),
    ()=>withFixture('{not json',file=>cli(file)),
    ()=>withFixture('[]',file=>cli(file)),
    ()=>withFixture(JSON.stringify({sections:[section('a','x')],maxBytes:'9'}),file=>cli(file)),
    ()=>withFixture(JSON.stringify({sections:[section('a','x',0,true)],maxBytes:1}),file=>cli(file)),
  ];
  for(const run of cases){
    const out=run();
    assert.equal(out.status,2);
    assert.equal(out.stdout,'');
    assert.notEqual(out.stderr,'');
  }
});

test('importing the module does not run the CLI',()=>{
  const run=spawnSync(process.execPath,['--input-type=module','-e',
    `import(${JSON.stringify(script)}).then(m=>process.stdout.write(typeof m.packContext))`],
    {encoding:'utf8'});
  assert.equal(run.status,0);
  assert.equal(run.stdout,'function');
  assert.equal(run.stderr,'');
});
